const server=http.createServer((req,res)=>{
    // console.log(__dirname)
    fs.mkdir(`${__dirname}/src/components`,{recursive:true},(err,data)=>{
        if(err){
            console.log("error")
            res.end()
        }
        else{
            console.log("directory created")
            res.end()
        }
    })
    res.end()
})
server.listen(port,()=>{
    console.log(`Server is running at ${port}`)
})